import{_ as c,C as n,o as d,c as l,a6 as s,E as t,j as a,a as r}from"./chunks/framework.5dd0l9Wo.js";const v=JSON.parse('{"title":"Access Control","description":"Vertical and horizontal privilege boundaries, IDOR, missing function-level checks, and every PortSwigger access control lab.","frontmatter":{"title":"Access Control","description":"Vertical and horizontal privilege boundaries, IDOR, missing function-level checks, and every PortSwigger access control lab."},"headers":[],"relativePath":"access-control/index.md","filePath":"access-control/index.md"}'),h={name:"access-control/index.md"};function p(u,e,m,b,f,y){const o=n("LabGroup"),i=n("TopicComplete");return d(),l("div",null,[e[0]||(e[0]=s(`<h1 id="access-control" tabindex="-1">Access Control <a class="header-anchor" href="#access-control" aria-label="Permalink to &quot;Access Control&quot;">​</a></h1><p class="wd-section-lede">Authentication answers &quot;who are you?&quot; Access control answers &quot;what may you do?&quot; Almost every serious web breach involves the second question being answered by the client, by a hidden URL, or by a check that runs on one request but not the next.</p><div class="wd-callout"><p><strong>The model.</strong> Authorisation must be enforced server-side, on every request, against the authenticated principal — not against a role parameter, a Referer header, a URL path, or a hidden form field. The moment the decision depends on something the client can send, the client owns the decision.</p></div><h2 id="vertical-vs-horizontal" tabindex="-1">Vertical vs horizontal <a class="header-anchor" href="#vertical-vs-horizontal" aria-label="Permalink to &quot;Vertical vs horizontal&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Question</th><th>Example</th></tr></thead><tbody><tr><td>Vertical</td><td>may a normal user reach admin functionality?</td><td><code>/admin/deleteUser</code> with no role check</td></tr><tr><td>Horizontal</td><td>may user A act on user B&#39;s data?</td><td><code>/my-account?id=victim</code></td></tr><tr><td>Context-dependent</td><td>may this user perform this action in this state?</td><td>multi-step checkout, step 3 skips payment</td></tr></tbody></table><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Request → session → principal (who) → policy (may they?) → object (which row?) → action</span></span>
<span class="line"><span>                │                          │                      │</span></span>
<span class="line"><span>          missing/forged             role from cookie      id from request</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="unprotected-functionality" tabindex="-1">Unprotected functionality <a class="header-anchor" href="#unprotected-functionality" aria-label="Permalink to &quot;Unprotected functionality&quot;">​</a></h2><p>The simplest failure: the admin function exists at a discoverable path and trusts that nobody will visit it. <code>robots.txt</code>, JavaScript bundles, and predictable paths (<code>/admin</code>, <code>/administrator</code>, <code>/admin-panel</code>) are the first places to look.</p>`,8)),t(o,{ids:"access-control-lab-unprotected-admin-functionality, access-control-lab-unprotected-admin-functionality-with-unpredictable-url"}),e[1]||(e[1]=a("h2",{id:"role-and-identity-taken-from-the-request",tabindex:"-1"},[r("Role and identity taken from the request "),a("a",{class:"header-anchor",href:"#role-and-identity-taken-from-the-request","aria-label":'Permalink to "Role and identity taken from the request"'},"​")],-1)),e[2]||(e[2]=a("p",null,[r("If the application stores the role in a cookie, a hidden field, or a query parameter, editing that value changes the authorisation decision. The same is true when the user identifier in a URL is trusted without an ownership check: that is "),a("strong",null,"IDOR"),r(" (insecure direct object reference).")],-1)),t(o,{ids:"access-control-lab-user-role-controlled-by-request-parameter, access-control-lab-user-role-can-be-modified-in-user-profile, access-control-lab-user-id-controlled-by-request-parameter, access-control-lab-user-id-controlled-by-request-parameter-with-unpredictable-user-ids, access-control-lab-user-id-controlled-by-request-parameter-with-data-leakage-in-redirect, access-control-lab-user-id-controlled-by-request-parameter-with-password-disclosure, access-control-lab-insecure-direct-object-references"}),e[3]||(e[3]=s('<details class="details custom-block"><summary>🔬 Under the Hood: where the authorisation check actually lives</summary><p>Frameworks offer several enforcement points, and bugs appear at the seams:</p><ul><li><strong>Route middleware</strong> (<code>@login_required</code>, Spring Security matchers) protects paths. A route that is not matched by the pattern is unprotected even if the controller checks roles internally.</li><li><strong>Function-level checks</strong> inside a controller can be skipped by a second route to the same function (an API alias, a legacy endpoint, a different HTTP method).</li><li><strong>Object-level checks</strong> must compare the object&#39;s owner to the session principal. Checking only that the user is logged in is authentication, not authorisation.</li></ul><p>The safe pattern is a single policy layer that receives <code>(principal, action, object)</code> and denies by default. Scattered <code>if user.isAdmin</code> checks drift.</p></details><h2 id="path-method-and-header-tricks" tabindex="-1">Path, method, and header tricks <a class="header-anchor" href="#path-method-and-header-tricks" aria-label="Permalink to &quot;Path, method, and header tricks&quot;">​</a></h2><p>Reverse proxies and frameworks disagree about which part of the request identifies the resource:</p><ul><li><strong>URL-based access control</strong> may inspect the path while the backend honours <code>X-Original-URL</code> or <code>X-Rewrite-URL</code>.</li><li><strong>Method-based access control</strong> may protect <code>POST /admin/upgrade</code> but not <code>GET</code> or <code>PUT</code> on the same route.</li><li><strong>Referer-based access control</strong> trusts a header the client controls.</li><li><strong>Multi-step processes</strong> enforce checks on the first step and forget them on the final one.</li></ul>',4)),t(o,{ids:"access-control-lab-url-based-access-control-can-be-circumvented, access-control-lab-method-based-access-control-can-be-circumvented, access-control-lab-multi-step-process-with-no-access-control-on-one-step, access-control-lab-referer-based-access-control"}),e[4]||(e[4]=s('<details class="details custom-block"><summary>⚙️ Engine Variations: proxy and framework path normalisation</summary><p>Access-control bypasses often come from two parsers disagreeing:</p><ul><li>Nginx and Apache normalise <code>..</code>, duplicate slashes, and percent-encoding differently.</li><li>Spring matches <code>/admin/**</code> but may also route <code>/admin;.css</code>, <code>/admin/..;/</code>, or <code>/ADMIN</code> depending on <code>PathPatternParser</code> settings.</li><li>Tomcat strips <code>;jsessionid</code> path parameters; a matcher that does not can be bypassed with <code>/admin;foo/</code>.</li><li>Cloud load balancers may forward the raw path while the application decodes it later.</li></ul><p>The lesson is structural: authorisation should be enforced at the same layer that dispatches the request, and tested with the exact bytes the backend will parse.</p></details><div class="wd-callout wd-callout--warn"><p><strong>Defence.</strong> Deny by default. Enforce on the server for every route and method. Derive the user id from the session, never from a parameter. Check object ownership on every read and write. Do not use hidden fields or headers as authority. Test with a second account, not just an unauthenticated one.</p></div>',2)),t(i,{"topic-id":"access-control-vulnerabilities",label:"Mark access control complete"})])}const w=c(h,[["render",p]]);export{v as __pageData,w as default};
